package com.smarthealth.model;
import java.time.LocalDateTime;import java.util.*;
/** Risk assessment and patient guidance. */
public class HealthResult {public enum RiskLevel{LOW,MEDIUM,HIGH}private RiskLevel riskLevel;private int riskScore;private String guidance;private List<String> preventionTips=new ArrayList<>();private LocalDateTime generatedAt=LocalDateTime.now();
 public HealthResult(){}public HealthResult(RiskLevel level,int score,String guidance,List<String> tips,LocalDateTime at){setRiskLevel(level);setRiskScore(score);this.guidance=guidance;setPreventionTips(tips);this.generatedAt=at;}public RiskLevel getRiskLevel(){return riskLevel;}public void setRiskLevel(RiskLevel v){riskLevel=Objects.requireNonNull(v);}public int getRiskScore(){return riskScore;}public void setRiskScore(int v){if(v<0||v>100)throw new IllegalArgumentException("Risk score must be 0-100");riskScore=v;}public String getGuidance(){return guidance;}public void setGuidance(String v){guidance=v;}public List<String> getPreventionTips(){return preventionTips;}public void setPreventionTips(List<String> v){preventionTips=v==null?new ArrayList<>():new ArrayList<>(v);}public LocalDateTime getGeneratedAt(){return generatedAt;}public void setGeneratedAt(LocalDateTime v){generatedAt=v;}@Override public String toString(){return "HealthResult{"+riskLevel+", score="+riskScore+"}";}@Override public boolean equals(Object o){return o instanceof HealthResult h&&Objects.equals(generatedAt,h.generatedAt)&&riskLevel==h.riskLevel;}@Override public int hashCode(){return Objects.hash(riskLevel,generatedAt);}}
